class Solution:
    def thousandSeparator(self, n: int) -> str:
        if n == 0:
            return "0"
        result = ""
        count = 0
        for digit in str(n)[::-1]:
            if count != 0 and count % 3 == 0:
                result += "."
            result += digit
            count += 1
        return result[::-1]
