def permute_a_palindrome(stg):
    char_count = {}
    for char in stg:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)
    return odd_count <= 1
```

